from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union
from stockflow.first_fit_decreasing import first_fit_decreasing


def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be > 0")

    merged: Dict[str, Tuple[int, int]] = {}
    for sku, qty, weight in lines:
        if qty <= 0 or weight <= 0:
            raise ValueError("Quantity and unit weight must be > 0")
        if weight > max_parcel_grams:
            raise ValueError(f"Single unit of {sku} exceeds max parcel weight")
        if sku in merged:
            q, w = merged[sku]
            if w != weight:
                raise ValueError(f"SKU {sku} has inconsistent unit weights")
            merged[sku] = (q + qty, weight)
        else:
            merged[sku] = (qty, weight)

    items = []
    chunk_info = {}
    cid = 0
    # To maintain consistency with FFD's expected sorting, we process SKUs
    # but group them into the largest chunks that fit in max_parcel_grams.
    for sku, (qty, weight) in merged.items():
        rem = qty
        per_chunk = max_parcel_grams // weight
        while rem > 0:
            take = min(rem, per_chunk)
            c_id = f"c{cid}"
            items.append((c_id, take * weight))
            chunk_info[c_id] = (sku, take)
            rem -= take
            cid += 1

    bins = first_fit_decreasing(items, max_parcel_grams)
    res = []
    for b in bins:
        p = {}
        for c_id, _ in b:
            sku, q = chunk_info[c_id]
            p[sku] = p.get(sku, 0) + q
        res.append(p)
